import type { Metadata } from "next";

export const SITE_URL = "https://www.kelsonqu.com";

export const JOB_TITLE = "Full-Stack & AI Engineer";

type OpenGraph = NonNullable<Metadata["openGraph"]>;
type Image = { url: string; width: number; height: number; alt: string };

/** The card generated by src/app/opengraph-image.tsx. */
export const SITE_OG_IMAGE: Image = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `Kelson Qu, ${JOB_TITLE}`,
};

/**
 * Metadata for one route. A page's `openGraph` and `twitter` replace the root
 * objects instead of merging (the root opengraph-image goes with them), so each
 * route restates its URL, title and card. Explicit `images` also outrank an
 * opengraph-image file in the same segment, so a route with its own card passes it.
 */
export function pageMetadata(
  path: string,
  title: string,
  description: string,
  openGraph: OpenGraph = { type: "website" },
  image: Image = SITE_OG_IMAGE,
): Metadata {
  const fullTitle = `${title} | Kelson Qu`;
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      siteName: "Kelson Qu Portfolio",
      locale: "en_US",
      url: path,
      title: fullTitle,
      description,
      ...openGraph,
      images: [image],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [image],
    },
  };
}

